fn put(mut outp &u8,i int,x int){mut bits:=u32(x);for k in 0..4{unsafe{outp[i*4+k]=u8(bits&255)};bits>>=8}}
@[export:'non_preemptive_priority_scheduling']
pub fn non_preemptive_priority_scheduling(v &i64,n usize,outp &u8,cap usize)i64{if n<4{return -1};count64:=unsafe{v[0]};if count64<1||count64>10||n!=usize(1+3*count64){return -1};count:=int(count64);mut a:=[10]int{};mut b:=[10]int{};mut p:=[10]int{};mut done:=[10]bool{};for i in 0..count{av:=unsafe{v[1+3*i]};bv:=unsafe{v[2+3*i]};pv:=unsafe{v[3+3*i]};if av<0||av>20||bv<1||bv>10||pv<0||pv>10{return -1};for j in 0..i{if p[j]==int(pv){return -1}};a[i]=int(av);b[i]=int(bv);p[i]=int(pv)};if cap<count*4||isnil(outp){return -2};mut now:=0;mut z:=0;for z<count{mut pick:=-1;for i in 0..count{if !done[i]&&a[i]<=now&&(pick<0||p[i]<p[pick]||(p[i]==p[pick]&&a[i]<a[pick])){pick=i}};if pick<0{mut next:=100000;for i in 0..count{if !done[i]&&a[i]<next{next=a[i]}};now=next;continue};done[pick]=true;put(mut outp,z,pick);z++;now+=b[pick]};return i64(count*4)}
